    EnTextos.textMensaTiempoAdelantoEntradasDeAireMenosm3,
    'Αυτή είναι η ώρα που τα παράθυρα θα κλείσουν πριν από την αποσύνδεση του εξαερισμού. Αυτή η ώρα δεν μπορεί να υπερβεί τον ελάχιστο χρόνο απενεργοποίησης (Μενού / Διαμόρφωση / Εξαερισμός / Προχωρημένος) και χαμηλότερος από τους ελάχιστους κύκλους όλων των σταδίων, συμπεριλαμβανομένου του σταδίου brooder, S0 και του φυσικού σταδίου.'
