    EnTextos.textMensaMinimoTiempoOff,
    ' Ο ελάχιστος χρόνος που πρέπει να παραμείνει ο ανεμιστήρας. Εάν ο χρόνος απενεργοποίησης είναι μικρότερος από αυτήν την παράμετρο, ο ανεμιστήρας δεν θα απενεργοποιηθεί και θα συνεχίσει να λειτουργεί. Αυτή η παράμετρος πρέπει να είναι μεγαλύτερη από τη χρονική εκκίνηση των εισόδων αέρα πριν από την εισαγωγή του εξαερισμού (Menu / Ρυθμίσεις / Depression / Περισσότερα)'
