    EnTextos.textMensModoRefrigeracionPorEtapas,
    ' Προοδευτική λειτουργία: Σε αυτή τη λειτουργία ενεργοποιείτε τις διαδρομές μία πίσω από μία. Περιστροφική λειτουργία: Σε αυτή τη λειτουργία ενεργοποιείτε ένα στάδιο μετά το άλλο, αλλά αλλάζετε το πρώτο στάδιο που είναι συνδεδεμένο. Το πρώτο στάδιο θα αλλάξει κάθε φορά που η ψύξη είναι απενεργοποιημένη'
